"""A nested JIT function must be generated by the caller's code generator class.

``CodeGenerator.call_JitFunction`` builds the generator for a callee. It used to
instantiate a hardcoded ``CodeGenerator(...)``, so whenever the caller's
generator was a subclass, the callee was still generated by the base class: the
subclass' ``__init__`` side effects and its ``visit_*`` overrides were silently
dropped for every nested JIT function. The fix is ``type(self)(...)``.

The contract is observed with a synthetic subclass, so this test is independent
of what any particular subclass does in ``__init__`` (e.g. the TLA dialect
building mounting, which lives in a separate change).
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import triton  # noqa: E402
import triton.language as tl  # noqa: E402
import triton.language.extra.tla as tla  # noqa: E402
from triton.language.extra.tla import compiler as tla_compiler  # noqa: E402
from triton.language.extra.tla.code_generator import TLACodeGenerator  # noqa: E402
from utils.tla_test_utils import compile_offline  # noqa: E402

SIGNATURE = {"X": "*u32"}


@triton.jit
def _inc(x):
    return x + 1


@tla.jit
def _kernel(X):
    with tla.scope.vector():
        buf = tla.alloc((1, ), tl.uint32)
        tla.store_scalar(buf, _inc(tl.program_id(0)))
        tla.store_ub_to_gm(buf, tla.view(X, (1, )))


def test_callee_uses_caller_generator_class(monkeypatch):
    """One generator for the kernel, one for the callee -- both the same class."""
    created = []

    class Recording(TLACodeGenerator):

        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            created.append(type(self))

    monkeypatch.setattr(tla_compiler, "TLACodeGenerator", Recording)
    module, _ctx = compile_offline(_kernel, SIGNATURE, {})
    ttir = str(module)

    # The callee really is outlined as a separate function, so the assertion
    # below is about who generated it, not about whether it exists at all.
    assert ttir.count("tt.func private") == 1, ttir
    assert ttir.count("tt.call") == 1, ttir

    names = [cls.__name__ for cls in created]
    assert created == [Recording, Recording], f"generator classes: {names}"
